INSERT INTO collection_pages VALUES('b969b998eecda6ff63378d3c855221f8093bd68e82a0908ac4c6ea7194aad4ec','834e0d82ae3a62ec2852ce7cb325748dda691aabe160f18dd907e44d7440427f','{"hasNext":false,"items":[{"author":{"account":{"login":"ejfkdev","providerType":"User"},"email":"ejfkdev@users.noreply.github.com","name":"ejfkdev"},"authoredDate":"2026-09-22T17:11:19Z","committedDate":"2026-09-22T17:11:19Z","committer":{"account":{"login":"ejfkdev","providerType":"User"},"email":"ejfkdev@users.noreply.github.com","name":"ejfkdev"},"observedAt":"2026-10-09T00:47:08.609Z","repositoryId":1381943805,"sha":"be885be8bec85d4aaf7e8b148140507c7f78c445"},{"author":{"account":{"login":"ejfkdev","providerType":"User"},"email":"ejfkdev@users.noreply.github.com","name":"ejfkdev"},"authoredDate":"2026-09-22T16:39:38Z","committedDate":"2026-09-22T16:39:38Z","committer":{"account":{"login":"ejfkdev","providerType":"User"},"email":"ejfkdev@users.noreply.github.com","name":"ejfkdev"},"observedAt":"2026-10-09T00:47:08.609Z","repositoryId":1381943805,"sha":"63a5aa2610d3dc5ebe572563ea366b8ee85b630b"},{"author":{"account":{"login":"ejfkdev","providerType":"User"},"email":"ejfkdev@users.noreply.github.com","name":"ejfkdev"},"authoredDate":"2026-09-22T16:35:01Z","committedDate":"2026-09-22T16:35:01Z","committer":{"account":{"login":"ejfkdev","providerType":"User"},"email":"ejfkdev@users.noreply.github.com","name":"ejfkdev"},"observedAt":"2026-10-09T00:47:08.609Z","repositoryId":1381943805,"sha":"d34452feb6c8cfbaf48b960e547cc06d99e0f2ae"}],"observedAt":"2026-10-09T00:47:08.609Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/152914458?v=4","events_url":"https://api.github.com/users/ejfkdev/events{/privacy}","followers_url":"https://api.github.com/users/ejfkdev/followers","following_url":"https://api.github.com/users/ejfkdev/following{/other_user}","gists_url":"https://api.github.com/users/ejfkdev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ejfkdev","id":152914458,"login":"ejfkdev","node_id":"U_kgDOCR1KGg","organizations_url":"https://api.github.com/users/ejfkdev/orgs","received_events_url":"https://api.github.com/users/ejfkdev/received_events","repos_url":"https://api.github.com/users/ejfkdev/repos","site_admin":false,"starred_url":"https://api.github.com/users/ejfkdev/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ejfkdev/subscriptions","type":"User","url":"https://api.github.com/users/ejfkdev","user_view_type":"public"},"comments_url":"https://api.github.com/repos/ejfkdev/pydj/commits/be885be8bec85d4aaf7e8b148140507c7f78c445/comments","commit":{"author":{"date":"2026-09-22T17:11:19Z","email":"ejfkdev@users.noreply.github.com","name":"ejfkdev"},"comment_count":0,"committer":{"date":"2026-09-22T17:11:19Z","email":"ejfkdev@users.noreply.github.com","name":"ejfkdev"},"message":"Fix scan abort when a transport returns a hand-built httpx.Response\n\ncoerce_response read the response URL with getattr(value, \"url\", None),\nwhich only absorbs AttributeError. An httpx.Response constructed directly\nrather than returned by a client raises RuntimeError on .url (\"the request\ninstance has not been set on this response\") and on .content for an unread\nstreaming response, so a scan using such a transport died with a\nRuntimeError from inside the library.\n\nAttribute reads now treat any failure as \"absent\": the text fallback and\nthe no-redirect case take over instead of aborting. Building response\nobjects by hand is a normal thing for a custom transport to do, and the\nREADME documents httpx responses as supported.\n\nFound by testing the published 0.1.0 wheel through pipx and uvx.\n\nAlso folds in documentation corrections noticed while verifying the\nrelease: the changelog said 23 plugins (26), and examples/README.md\npinned a wheel filename that goes stale on every version bump.","tree":{"sha":"e62d97e233823139d91c0c810c98dd11c3a32e59","url":"https://api.github.com/repos/ejfkdev/pydj/git/trees/e62d97e233823139d91c0c810c98dd11c3a32e59"},"url":"https://api.github.com/repos/ejfkdev/pydj/git/commits/be885be8bec85d4aaf7e8b148140507c7f78c445","verification":{"payload":"tree e62d97e233823139d91c0c810c98dd11c3a32e59\nparent 63a5aa2610d3dc5ebe572563ea366b8ee85b630b\nauthor ejfkdev <ejfkdev@users.noreply.github.com> 1790097079 +0800\ncommitter ejfkdev <ejfkdev@users.noreply.github.com> 1790097079 +0800\n\nFix scan abort when a transport returns a hand-built httpx.Response\n\ncoerce_response read the response URL with getattr(value, \"url\", None),\nwhich only absorbs AttributeError. An httpx.Response constructed directly\nrather than returned by a client raises RuntimeError on .url (\"the request\ninstance has not been set on this response\") and on .content for an unread\nstreaming response, so a scan using such a transport died with a\nRuntimeError from inside the library.\n\nAttribute reads now treat any failure as \"absent\": the text fallback and\nthe no-redirect case take over instead of aborting. Building response\nobjects by hand is a normal thing for a custom transport to do, and the\nREADME documents httpx responses as supported.\n\nFound by testing the published 0.1.0 wheel through pipx and uvx.\n\nAlso folds in documentation corrections noticed while verifying the\nrelease: the changelog said 23 plugins (26), and examples/README.md\npinned a wheel filename that goes stale on every version bump.\n","reason":"valid","signature":"-----BEGIN SSH SIGNATURE-----\nU1NIU0lHAAAAAQAAADMAAAALc3NoLWVkMjU1MTkAAAAgS5joz/txa9gCHDmkRjODQR26Zj\nxLefxTaIQIownpJgQAAAADZ2l0AAAAAAAAAAZzaGE1MTIAAABTAAAAC3NzaC1lZDI1NTE5\nAAAAQKYSXBngVf5yC5Zb3lUkgIhd7rqvoR6BSea76dQgeGPZhqJPU4KjfrFj0U8X3wuOOT\nUyjfmfb2braQLHzKk4WQw=\n-----END SSH SIGNATURE-----","verified":true,"verified_at":"2026-09-22T17:11:24Z"}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/152914458?v=4","events_url":"https://api.github.com/users/ejfkdev/events{/privacy}","followers_url":"https://api.github.com/users/ejfkdev/followers","following_url":"https://api.github.com/users/ejfkdev/following{/other_user}","gists_url":"https://api.github.com/users/ejfkdev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ejfkdev","id":152914458,"login":"ejfkdev","node_id":"U_kgDOCR1KGg","organizations_url":"https://api.github.com/users/ejfkdev/orgs","received_events_url":"https://api.github.com/users/ejfkdev/received_events","repos_url":"https://api.github.com/users/ejfkdev/repos","site_admin":false,"starred_url":"https://api.github.com/users/ejfkdev/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ejfkdev/subscriptions","type":"User","url":"https://api.github.com/users/ejfkdev","user_view_type":"public"},"html_url":"https://github.com/ejfkdev/pydj/commit/be885be8bec85d4aaf7e8b148140507c7f78c445","node_id":"C_kwDOUl7J_doAKGJlODg1YmU4YmVjODVkNGFhZjdlOGIxNDgxNDA1MDdjN2Y3OGM0NDU","parents":[{"html_url":"https://github.com/ejfkdev/pydj/commit/63a5aa2610d3dc5ebe572563ea366b8ee85b630b","sha":"63a5aa2610d3dc5ebe572563ea366b8ee85b630b","url":"https://api.github.com/repos/ejfkdev/pydj/commits/63a5aa2610d3dc5ebe572563ea366b8ee85b630b"}],"sha":"be885be8bec85d4aaf7e8b148140507c7f78c445","url":"https://api.github.com/repos/ejfkdev/pydj/commits/be885be8bec85d4aaf7e8b148140507c7f78c445"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/152914458?v=4","events_url":"https://api.github.com/users/ejfkdev/events{/privacy}","followers_url":"https://api.github.com/users/ejfkdev/followers","following_url":"https://api.github.com/users/ejfkdev/following{/other_user}","gists_url":"https://api.github.com/users/ejfkdev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ejfkdev","id":152914458,"login":"ejfkdev","node_id":"U_kgDOCR1KGg","organizations_url":"https://api.github.com/users/ejfkdev/orgs","received_events_url":"https://api.github.com/users/ejfkdev/received_events","repos_url":"https://api.github.com/users/ejfkdev/repos","site_admin":false,"starred_url":"https://api.github.com/users/ejfkdev/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ejfkdev/subscriptions","type":"User","url":"https://api.github.com/users/ejfkdev","user_view_type":"public"},"comments_url":"https://api.github.com/repos/ejfkdev/pydj/commits/63a5aa2610d3dc5ebe572563ea366b8ee85b630b/comments","commit":{"author":{"date":"2026-09-22T16:39:38Z","email":"ejfkdev@users.noreply.github.com","name":"ejfkdev"},"comment_count":0,"committer":{"date":"2026-09-22T16:39:38Z","email":"ejfkdev@users.noreply.github.com","name":"ejfkdev"},"message":"Fix two CI failures found on the first run\n\n- Assert on `Path` components instead of a literal \"js/static_app.js\"\n  suffix. Windows uses a backslash separator, so the string assertions in\n  test_core.py could never match there.\n- Assert `License-Expression: MPL-2.0` in the wheel metadata. The license\n  is written as a PEP 639 expression, so the old `License:` assertion\n  failed against correct metadata.","tree":{"sha":"793fb186eca87990311c5662d4128986e65e25b0","url":"https://api.github.com/repos/ejfkdev/pydj/git/trees/793fb186eca87990311c5662d4128986e65e25b0"},"url":"https://api.github.com/repos/ejfkdev/pydj/git/commits/63a5aa2610d3dc5ebe572563ea366b8ee85b630b","verification":{"payload":"tree 793fb186eca87990311c5662d4128986e65e25b0\nparent d34452feb6c8cfbaf48b960e547cc06d99e0f2ae\nauthor ejfkdev <ejfkdev@users.noreply.github.com> 1790095178 +0800\ncommitter ejfkdev <ejfkdev@users.noreply.github.com> 1790095178 +0800\n\nFix two CI failures found on the first run\n\n- Assert on `Path` components instead of a literal \"js/static_app.js\"\n  suffix. Windows uses a backslash separator, so the string assertions in\n  test_core.py could never match there.\n- Assert `License-Expression: MPL-2.0` in the wheel metadata. The license\n  is written as a PEP 639 expression, so the old `License:` assertion\n  failed against correct metadata.\n","reason":"valid","signature":"-----BEGIN SSH SIGNATURE-----\nU1NIU0lHAAAAAQAAADMAAAALc3NoLWVkMjU1MTkAAAAgS5joz/txa9gCHDmkRjODQR26Zj\nxLefxTaIQIownpJgQAAAADZ2l0AAAAAAAAAAZzaGE1MTIAAABTAAAAC3NzaC1lZDI1NTE5\nAAAAQGeBn+0wkz0sbc9Z/NC1Wjsu2HRSX6Z+klQdAh2h//aUFD38M76wI4DPPAZYhBvoE8\n3fHbNw6dB8wy0KdaQW3g4=\n-----END SSH SIGNATURE-----","verified":true,"verified_at":"2026-09-22T16:39:42Z"}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/152914458?v=4","events_url":"https://api.github.com/users/ejfkdev/events{/privacy}","followers_url":"https://api.github.com/users/ejfkdev/followers","following_url":"https://api.github.com/users/ejfkdev/following{/other_user}","gists_url":"https://api.github.com/users/ejfkdev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ejfkdev","id":152914458,"login":"ejfkdev","node_id":"U_kgDOCR1KGg","organizations_url":"https://api.github.com/users/ejfkdev/orgs","received_events_url":"https://api.github.com/users/ejfkdev/received_events","repos_url":"https://api.github.com/users/ejfkdev/repos","site_admin":false,"starred_url":"https://api.github.com/users/ejfkdev/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ejfkdev/subscriptions","type":"User","url":"https://api.github.com/users/ejfkdev","user_view_type":"public"},"html_url":"https://github.com/ejfkdev/pydj/commit/63a5aa2610d3dc5ebe572563ea366b8ee85b630b","node_id":"C_kwDOUl7J_doAKDYzYTVhYTI2MTBkM2RjNWViZTU3MjU2M2VhMzY2YjhlZTg1YjYzMGI","parents":[{"html_url":"https://github.com/ejfkdev/pydj/commit/d34452feb6c8cfbaf48b960e547cc06d99e0f2ae","sha":"d34452feb6c8cfbaf48b960e547cc06d99e0f2ae","url":"https://api.github.com/repos/ejfkdev/pydj/commits/d34452feb6c8cfbaf48b960e547cc06d99e0f2ae"}],"sha":"63a5aa2610d3dc5ebe572563ea366b8ee85b630b","url":"https://api.github.com/repos/ejfkdev/pydj/commits/63a5aa2610d3dc5ebe572563ea366b8ee85b630b"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/152914458?v=4","events_url":"https://api.github.com/users/ejfkdev/events{/privacy}","followers_url":"https://api.github.com/users/ejfkdev/followers","following_url":"https://api.github.com/users/ejfkdev/following{/other_user}","gists_url":"https://api.github.com/users/ejfkdev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ejfkdev","id":152914458,"login":"ejfkdev","node_id":"U_kgDOCR1KGg","organizations_url":"https://api.github.com/users/ejfkdev/orgs","received_events_url":"https://api.github.com/users/ejfkdev/received_events","repos_url":"https://api.github.com/users/ejfkdev/repos","site_admin":false,"starred_url":"https://api.github.com/users/ejfkdev/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ejfkdev/subscriptions","type":"User","url":"https://api.github.com/users/ejfkdev","user_view_type":"public"},"comments_url":"https://api.github.com/repos/ejfkdev/pydj/commits/d34452feb6c8cfbaf48b960e547cc06d99e0f2ae/comments","commit":{"author":{"date":"2026-09-22T16:35:01Z","email":"ejfkdev@users.noreply.github.com","name":"ejfkdev"},"comment_count":0,"committer":{"date":"2026-09-22T16:35:01Z","email":"ejfkdev@users.noreply.github.com","name":"ejfkdev"},"message":"Initial release: pydj 0.1.0\n\nDiscover dynamically loaded JavaScript and source maps from websites,\nthen restore the original sources.\n\n- CLI and library interfaces (no HTTP API, no MCP server)\n- 26 built-in plugins covering webpack, Vite, Next.js, Nuxt, SvelteKit,\n  Module Federation, UmiJS, Trunk, EMP and the common microfrontend shells\n- Browser TLS fingerprint impersonation via curl-cffi\n- Injectable HTTP transport, so callers can supply their own TLS layer\n- Source map v3 decoding with sourcesContent and VLQ fallback\n- On-disk cache reuse, cache layout and meta.json shared with the Go original","tree":{"sha":"300612f9c130cef51a4152528d631c7447657668","url":"https://api.github.com/repos/ejfkdev/pydj/git/trees/300612f9c130cef51a4152528d631c7447657668"},"url":"https://api.github.com/repos/ejfkdev/pydj/git/commits/d34452feb6c8cfbaf48b960e547cc06d99e0f2ae","verification":{"payload":"tree 300612f9c130cef51a4152528d631c7447657668\nauthor ejfkdev <ejfkdev@users.noreply.github.com> 1790094901 +0800\ncommitter ejfkdev <ejfkdev@users.noreply.github.com> 1790094901 +0800\n\nInitial release: pydj 0.1.0\n\nDiscover dynamically loaded JavaScript and source maps from websites,\nthen restore the original sources.\n\n- CLI and library interfaces (no HTTP API, no MCP server)\n- 26 built-in plugins covering webpack, Vite, Next.js, Nuxt, SvelteKit,\n  Module Federation, UmiJS, Trunk, EMP and the common microfrontend shells\n- Browser TLS fingerprint impersonation via curl-cffi\n- Injectable HTTP transport, so callers can supply their own TLS layer\n- Source map v3 decoding with sourcesContent and VLQ fallback\n- On-disk cache reuse, cache layout and meta.json shared with the Go original\n","reason":"valid","signature":"-----BEGIN SSH SIGNATURE-----\nU1NIU0lHAAAAAQAAADMAAAALc3NoLWVkMjU1MTkAAAAgS5joz/txa9gCHDmkRjODQR26Zj\nxLefxTaIQIownpJgQAAAADZ2l0AAAAAAAAAAZzaGE1MTIAAABTAAAAC3NzaC1lZDI1NTE5\nAAAAQHNRwo+g6BUeJ9xSun34g6yQs1AFEyaTnSLOT4NxYcRcaPBzrr8FoPGyczFPbGapiT\nMSxrsCeqkBbB5pQD3JAQ0=\n-----END SSH SIGNATURE-----","verified":true,"verified_at":"2026-09-22T16:35:14Z"}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/152914458?v=4","events_url":"https://api.github.com/users/ejfkdev/events{/privacy}","followers_url":"https://api.github.com/users/ejfkdev/followers","following_url":"https://api.github.com/users/ejfkdev/following{/other_user}","gists_url":"https://api.github.com/users/ejfkdev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ejfkdev","id":152914458,"login":"ejfkdev","node_id":"U_kgDOCR1KGg","organizations_url":"https://api.github.com/users/ejfkdev/orgs","received_events_url":"https://api.github.com/users/ejfkdev/received_events","repos_url":"https://api.github.com/users/ejfkdev/repos","site_admin":false,"starred_url":"https://api.github.com/users/ejfkdev/star