INSERT INTO collection_pages VALUES('bc2b7c8e2370b06eabdaeabe2b46ea1dedc9f96589cc8698382bb2d1d46a57b1','40eb33e9daddfaf9f1fd32481019eea9eb27430704e69e218d60107f5b725cf4','{"hasNext":false,"items":[{"author":{"account":{"login":"bertozo","providerType":"User"},"email":"rodolfobertozo@gmail.com","name":"Rodolfo Bertozo"},"authoredDate":"2026-09-23T12:47:22Z","committedDate":"2026-09-23T12:47:22Z","committer":{"account":{"login":"bertozo","providerType":"User"},"email":"rodolfobertozo@gmail.com","name":"Rodolfo Bertozo"},"observedAt":"2026-10-09T00:47:51.788Z","repositoryId":1383431458,"sha":"20e5293518ee8638f7feb762e8e3fac1e4de36d9"}],"observedAt":"2026-10-09T00:47:51.788Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/6954839?v=4","events_url":"https://api.github.com/users/bertozo/events{/privacy}","followers_url":"https://api.github.com/users/bertozo/followers","following_url":"https://api.github.com/users/bertozo/following{/other_user}","gists_url":"https://api.github.com/users/bertozo/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/bertozo","id":6954839,"login":"bertozo","node_id":"MDQ6VXNlcjY5NTQ4Mzk=","organizations_url":"https://api.github.com/users/bertozo/orgs","received_events_url":"https://api.github.com/users/bertozo/received_events","repos_url":"https://api.github.com/users/bertozo/repos","site_admin":false,"starred_url":"https://api.github.com/users/bertozo/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/bertozo/subscriptions","type":"User","url":"https://api.github.com/users/bertozo","user_view_type":"public"},"comments_url":"https://api.github.com/repos/bertozo/studies-microservices/commits/20e5293518ee8638f7feb762e8e3fac1e4de36d9/comments","commit":{"author":{"date":"2026-09-23T12:47:22Z","email":"rodolfobertozo@gmail.com","name":"Rodolfo Bertozo"},"comment_count":0,"committer":{"date":"2026-09-23T12:47:22Z","email":"rodolfobertozo@gmail.com","name":"Rodolfo Bertozo"},"message":"Initial commit: e-commerce microservices + microfrontends study stack\n\nLocal, container-only stack for studying service and frontend boundaries:\n\n- Three FastAPI services, one database each (product/MySQL, order/MongoDB,\n  user/PostgreSQL), with no cross-database access. The user service is the only\n  JWT issuer; the others validate the shared secret.\n- Three React microfrontends federated with Webpack 5 Module Federation, wired\n  by a window-scoped event bus because federated bundles do not share module\n  scope.\n- nginx API gateway owning routing and CORS.\n- Prometheus + Loki + Grafana, with a provisioned overview dashboard.\n\nTrade-offs and known limitations are documented in docs/ARCHITECTURE.md.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"b32a518ef64d042abdbca1e980164990941cbc9d","url":"https://api.github.com/repos/bertozo/studies-microservices/git/trees/b32a518ef64d042abdbca1e980164990941cbc9d"},"url":"https://api.github.com/repos/bertozo/studies-microservices/git/commits/20e5293518ee8638f7feb762e8e3fac1e4de36d9","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/6954839?v=4","events_url":"https://api.github.com/users/bertozo/events{/privacy}","followers_url":"https://api.github.com/users/bertozo/followers","following_url":"https://api.github.com/users/bertozo/following{/other_user}","gists_url":"https://api.github.com/users/bertozo/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/bertozo","id":6954839,"login":"bertozo","node_id":"MDQ6VXNlcjY5NTQ4Mzk=","organizations_url":"https://api.github.com/users/bertozo/orgs","received_events_url":"https://api.github.com/users/bertozo/received_events","repos_url":"https://api.github.com/users/bertozo/repos","site_admin":false,"starred_url":"https://api.github.com/users/bertozo/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/