ures leave it out.","tree":{"sha":"4300c82c37838aff1589954d665849e641d58602","url":"https://api.github.com/repos/olehwebdev/console-editor/git/trees/4300c82c37838aff1589954d665849e641d58602"},"url":"https://api.github.com/repos/olehwebdev/console-editor/git/commits/a76d0c28870d2712667b9843384becf983293d7a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/10379680?v=4","events_url":"https://api.github.com/users/olehwebdev/events{/privacy}","followers_url":"https://api.github.com/users/olehwebdev/followers","following_url":"https://api.github.com/users/olehwebdev/following{/other_user}","gists_url":"https://api.github.com/users/olehwebdev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/olehwebdev","id":10379680,"login":"olehwebdev","node_id":"MDQ6VXNlcjEwMzc5Njgw","organizations_url":"https://api.github.com/users/olehwebdev/orgs","received_events_url":"https://api.github.com/users/olehwebdev/received_events","repos_url":"https://api.github.com/users/olehwebdev/repos","site_admin":false,"starred_url":"https://api.github.com/users/olehwebdev/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/olehwebdev/subscriptions","type":"User","url":"https://api.github.com/users/olehwebdev","user_view_type":"public"},"html_url":"https://github.com/olehwebdev/console-editor/commit/a76d0c28870d2712667b9843384becf983293d7a","node_id":"C_kwDOUoGmVtoAKGE3NmQwYzI4ODcwZDI3MTI2NjdiOTg0MzM4NGJlY2Y5ODMyOTNkN2E","parents":[{"html_url":"https://github.com/olehwebdev/console-editor/commit/9c7cc546fcf22e4b6a0b0b449000282e614c6b42","sha":"9c7cc546fcf22e4b6a0b0b449000282e614c6b42","url":"https://api.github.com/repos/olehwebdev/console-editor/commits/9c7cc546fcf22e4b6a0b0b449000282e614c6b42"}],"sha":"a76d0c28870d2712667b9843384becf983293d7a","url":"https://api.github.com/repos/olehwebdev/console-editor/commits/a76d0c28870d2712667b9843384b