_id":"C_kwDOUoGmVtoAKGUyNmNhMGRlZWVkMWJlZTZiZmNhZTM3ZDk5OTJhODYzMGVhZmFiZDQ","parents":[{"html_url":"https://github.com/olehwebdev/console-editor/commit/0cbb9a2398bc1c36468fd9f9f2e01000cf1ce900","sha":"0cbb9a2398bc1c36468fd9f9f2e01000cf1ce900","url":"https://api.github.com/repos/olehwebdev/console-editor/commits/0cbb9a2398bc1c36468fd9f9f2e01000cf1ce900"}],"sha":"e26ca0deeed1bee6bfcae37d9992a8630eafabd4","url":"https://api.github.com/repos/olehwebdev/console-editor/commits/e26ca0deeed1bee6bfcae37d9992a8630eafabd4"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/10379680?v=4","events_url":"https://api.github.com/users/olehwebdev/events{/privacy}","followers_url":"https://api.github.com/users/olehwebdev/followers","following_url":"https://api.github.com/users/olehwebdev/following{/other_user}","gists_url":"https://api.github.com/users/olehwebdev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/olehwebdev","id":10379680,"login":"olehwebdev","node_id":"MDQ6VXNlcjEwMzc5Njgw","organizations_url":"https://api.github.com/users/olehwebdev/orgs","received_events_url":"https://api.github.com/users/olehwebdev/received_events","repos_url":"https://api.github.com/users/olehwebdev/repos","site_admin":false,"starred_url":"https://api.github.com/users/olehwebdev/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/olehwebdev/subscriptions","type":"User","url":"https://api.github.com/users/olehwebdev","user_view_type":"public"},"comments_url":"https://api.github.com/repos/olehwebdev/console-editor/commits/0cbb9a2398bc1c36468fd9f9f2e01000cf1ce900/comments","commit":{"author":{"date":"2026-09-26T19:15:46Z","email":"bigbooooooom@gmail.com","name":"olehwebdev"},"comment_count":0,"committer":{"date":"2026-09-26T19:15:46Z","email":"bigbooooooom@gmail.com","name":"olehwebdev"},"message":"Export and import a workspace''s overrides and rules as one file\n\nExport writes the active workspace''s overrides (content, the base when it\ndiffers, match, on/off, a response override''s settings) and rules to one\nJSON file through a save dialog. Import adds a file''s to the active\nworkspace: each entry is checked as the app''s own input, one the\nworkspace already has is left out (its own version is kept), and the\ntoast says what was added and left out before the page reloads.\n\nBoth are in a menu on the Explorer''s Overrides section and in the\npalette.","tree":{"sha":"28b9de31310d7ce5e6d6342fc620ee926d46db71","url":"https://api.github.com/repos/olehwebdev/console-editor/git/trees/28b9de31310d7ce5e6d6342fc620ee926d46db71"},"url":"https://api.github.com/repos/olehwebdev/console-editor/git/commits/0cbb9a2398bc1c36468fd9f9f2e01000cf1ce900","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/10379680?v=4","events_url":"https://api.github.com/users/olehwebdev/events{/privacy}","followers_url":"https://api.github.com/users/olehwebdev/followers","following_url":"https://api.github.com/users/olehwebdev/following{/other_user}","gists_url":"https://api.github.com/users/olehwebdev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/olehwebdev","id":10379680,"login":"olehwebdev","node_id":"MDQ6VXNlcjEwMzc5Njgw","organizations_url":"https://api.github.com/users/olehwebdev/orgs","received_events_url":"https://api.github.com/users/olehwebdev/received_events","repos_url":"https://api.github.com/users/olehwebdev/repos","site_admin":false,"starred_url":"https://api.github.com/users/olehwebdev/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/olehwebdev/subscriptions","type":"User","url":"https://api.github.com/users/olehwebdev","user_view_type":"public"},"html_url":"https://github.com/olehwebdev/console-editor/commit/0cbb9a2398bc1c36468fd9f9f2e01000cf1ce900","node_id":"C_kwDOUoGmVtoAKDBjYmI5YTIzOThiYzFjMzY0NjhmZDlmOWYyZTAxMDAwY2YxY2U5MDA","parents":[{"html_url":"https